import{_ as e,o,c as r,a3 as t}from"./chunks/framework.Dj4Lt7vj.js";const p=JSON.parse('{"title":"通用配置","description":"","frontmatter":{"title":"通用配置"},"headers":[],"relativePath":"solution/general.md","filePath":"solution/general.md","lastUpdated":1787948622000}'),l={name:"solution/general.md"};function i(n,a,d,s,h,c){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="通用配置" tabindex="-1">通用配置 <a class="header-anchor" href="#通用配置" aria-label="Permalink to &quot;通用配置&quot;">​</a></h1><p>「通用配置」管方案级的全局行为：消息读取节奏、订单检测、夜间服务和新客问候。</p><p>入口：方案编辑器 → 「通用配置」。改完记得点右下角「保存设置」。</p><h2 id="基础设置" tabindex="-1">基础设置 <a class="header-anchor" href="#基础设置" aria-label="Permalink to &quot;基础设置&quot;">​</a></h2><h3 id="时间间隔" tabindex="-1">时间间隔 <a class="header-anchor" href="#时间间隔" aria-label="Permalink to &quot;时间间隔&quot;">​</a></h3><p>AI 读取和回复消息的间隔，单位秒，建议 1–10 秒。值越小回复越及时；适当调大会显得更像人工在打字。</p><h3 id="开启订单检测" tabindex="-1">开启订单检测 <a class="header-anchor" href="#开启订单检测" aria-label="Permalink to &quot;开启订单检测&quot;">​</a></h3><p>开启后，AI 检测到顾客<strong>已下单</strong>时自动转人工，避免 AI 在成交环节说错话。</p><p>配套的「检测到订单时回复」可以自定义检测到订单后的回复语。输入 <code>/</code> 可以插入转接指令，输入 <code>@</code> 可以选择图片。</p><h3 id="考虑客服回复" tabindex="-1">考虑客服回复 <a class="header-anchor" href="#考虑客服回复" aria-label="Permalink to &quot;考虑客服回复&quot;">​</a></h3><p>开启后，如果人工客服已经回复了顾客，AI 不再回复上一条消息。人机混合值班时建议开启，避免顾客同时收到两个回答。</p><h3 id="兜底回复" tabindex="-1">兜底回复 <a class="header-anchor" href="#兜底回复" aria-label="Permalink to &quot;兜底回复&quot;">​</a></h3><p>AI 无法正常回复时的兜底处理。<strong>默认是转人工</strong>，也可以改成发送固定话术。输入框同样支持 <code>/</code> 插入指令、<code>@</code> 选择图片。</p><h2 id="服务策略" tabindex="-1">服务策略 <a class="header-anchor" href="#服务策略" aria-label="Permalink to &quot;服务策略&quot;">​</a></h2><h3 id="夜间服务模式" tabindex="-1">夜间服务模式 <a class="header-anchor" href="#夜间服务模式" aria-label="Permalink to &quot;夜间服务模式&quot;">​</a></h3><p>指定时段内，本该转人工的回复改为发送夜间话术，<strong>不转人工</strong>。适合下班后没有客服值守的时段。</p><ul><li>时间段支持跨天，比如 22:00 – 08:00。</li><li>夜间话术可以配多条，每次接待随机取一条，顾客不会连着收到同一句。</li><li>话术支持 <code>@</code> 插入图片。</li></ul><h3 id="新客自动问候" tabindex="-1">新客自动问候 <a class="header-anchor" href="#新客自动问候" aria-label="Permalink to &quot;新客自动问候&quot;">​</a></h3><p>新客、或超过 24 小时没有互动的顾客首次发言时，自动发送问候语。问候语最长 500 字，支持 <code>@</code> 插入图片。</p><h2 id="建议的组合" tabindex="-1">建议的组合 <a class="header-anchor" href="#建议的组合" aria-label="Permalink to &quot;建议的组合&quot;">​</a></h2><ul><li><strong>有夜班客服</strong>：不开夜间模式，转人工正常走。</li><li><strong>晚上没人值守</strong>：开夜间模式，话术里写清「已留言、明早处理」，第二天用<a href="/aicare-docs/workspace/records">聊天记录</a>的待跟进筛选逐个回访。</li><li><strong>人机混合值班</strong>：开「考虑客服回复」，避免抢答。</li></ul>',21)])])}const _=e(l,[["render",i]]);export{p as __pageData,_ as default};
